const incoming = $input.first()?.json ?? {};
const body = incoming.body && Object.keys(incoming.body).length > 0 ? incoming.body : {};
const sampleAlert = {
  alert_id: 'alert-2026-05-20-invoicebridge-5xx',
  incident_id: 'inc-invoicebridge-2026-05-20-001',
  source: 'mock-cloudwatch',
  provider: 'aws',
  environment: 'staging',
  service: 'invoicebridge-api',
  resource: 'alb/target-group/invoicebridge-api',
  severity: 'sev2',
  status: 'firing',
  started_at: '2026-05-20T14:05:00Z',
  summary: 'HTTP 5xx error rate for invoicebridge-api exceeded 8 percent for 10 minutes.',
  metric_context: {
    metric_name: 'HTTPCode_Target_5XX_Count',
    error_rate_percent: 8.7,
    threshold_percent: 5,
    request_count: 18420,
    error_count: 1603,
    window: '10m'
  },
  labels: {
    team: 'platform-apps',
    region: 'us-east-1',
    runbook: 'runbooks/high-5xx-error-rate.md',
    customer_impact: 'Invoice PDF generation and webhook delivery are intermittently failing.'
  }
};
const alert = { ...sampleAlert, ...body };
return [{
  json: {
    alert,
    context_source: 'sample-alerts/invoicebridge-5xx-alert.json',
    demo_mode: 'mock',
    external_api_calls: 0,
    production_changes: 0
  }
}];

const item = $input.first().json;
const sampleLogs = {
  source_file: 'sample-logs/invoicebridge-errors.json',
  time_window: {
    start: '2026-05-20T13:55:00Z',
    end: '2026-05-20T14:15:00Z'
  },
  release_events: [
    {
      timestamp: '2026-05-20T13:58:22Z',
      release: 'invoicebridge-api@2026.05.20.3',
      commit: 'mock-7f3a91c',
      actor: 'mock-deployer',
      change_summary: 'Updated invoice PDF renderer timeout and webhook retry handling.'
    }
  ],
  error_summary: {
    sampled_5xx_entries: 4,
    dominant_route: '/v1/invoices/render',
    statuses: {
      '500': 1,
      '502': 2,
      '504': 1
    },
    sample_request_ids: ['req-inv-1038', 'req-inv-1075', 'req-inv-1102', 'req-inv-1164']
  }
};
const runbook = {
  source_file: 'runbooks/high-5xx-error-rate.md',
  title: 'High 5xx Error Rate Runbook',
  matched_terms: ['5xx', 'timeout', 'release', 'rollback', 'customer-facing'],
  approval_required_actions: [
    'Rollback a release',
    'Restart workloads',
    'Scale service capacity',
    'Change timeout, retry, queue, or rate-limit configuration',
    'Send customer-facing status updates'
  ]
};
return [{
  json: {
    ...item,
    logs: sampleLogs,
    runbook,
    loading_placeholders: {
      log_loader: 'Placeholder for future log source adapter. No log API call is made.',
      runbook_loader: 'Placeholder for future docs or repository lookup. Static sample content is embedded.'
    }
  }
}];

const item = $input.first().json;
const alert = item.alert;
const logs = item.logs;
const triage = {
  stage: 'triage',
  mode: 'mock-ai-agent-placeholder',
  finding: `${alert.service} is above its 5xx threshold at ${alert.metric_context.error_rate_percent} percent over ${alert.metric_context.window}.`,
  impact: alert.labels.customer_impact,
  severity: alert.severity,
  evidence: [
    alert.summary,
    `${logs.error_summary.sampled_5xx_entries} sampled 5xx log entries.`,
    `Dominant route: ${logs.error_summary.dominant_route}.`
  ]
};
return [{ json: { ...item, triage } }];

const item = $input.first().json;
const release = item.logs.release_events[0];
const releaseCorrelation = {
  stage: 'release_correlation',
  mode: 'mock-ai-agent-placeholder',
  finding: `Errors are concentrated after ${release.release}, deployed at ${release.timestamp}.`,
  confidence: 'medium',
  release,
  caveat: 'Correlation is not proof of root cause; continue read-only checks before proposing remediation.'
};
return [{ json: { ...item, release_correlation: releaseCorrelation } }];

const item = $input.first().json;
const runbookLookup = {
  stage: 'runbook_lookup',
  mode: 'mock-ai-agent-placeholder',
  selected_runbook: item.runbook.source_file,
  matched_terms: item.runbook.matched_terms,
  reason: 'Alert and logs indicate elevated HTTP 5xx responses with timeout and release-correlation signals.'
};
const nextStepPlan = {
  stage: 'next_step_planning',
  mode: 'mock-ai-agent-placeholder',
  read_only_steps: [
    'Review route-level 5xx rate for /v1/invoices/render and /v1/webhooks/deliver.',
    'Compare errors before and after invoicebridge-api@2026.05.20.3.',
    'Inspect renderer timeout metrics and queue depth using approved read-only telemetry.',
    'Prepare an approval request before rollback, restart, scaling, or config changes.'
  ],
  approval_required_steps: item.runbook.approval_required_actions,
  blocked_steps: ['No production mutation is allowed from this demo workflow.']
};
return [{ json: { ...item, runbook_lookup: runbookLookup, next_step_plan: nextStepPlan } }];

const item = $input.first().json;
const approvalGate = {
  stage: 'approval_gate',
  mode: 'placeholder',
  decision: 'HUMAN_APPROVAL_REQUIRED',
  allowed_now: ['Read-only diagnosis', 'Incident documentation', 'Draft follow-up tasks'],
  blocked_until_approval: item.next_step_plan.approval_required_steps,
  message: 'No rollback, restart, scaling, config change, or customer-facing message may run without human approval.'
};
return [{ json: { ...item, approval_gate: approvalGate } }];

const item = $input.first().json;
const githubIssue = {
  stage: 'github_issue_placeholder',
  mode: 'placeholder_no_credentials',
  would_create_issue: true,
  repository: 'mock-owner/mock-repo',
  title: `[${item.alert.severity.toUpperCase()}] ${item.alert.service} elevated 5xx rate`,
  body_preview: [
    item.triage.finding,
    item.release_correlation.finding,
    `Runbook: ${item.runbook_lookup.selected_runbook}`,
    'Approval required before rollback or configuration change.'
  ].join('\n')
};
return [{ json: { ...item, github_issue_placeholder: githubIssue } }];

const item = $input.first().json;
const auditInsert = {
  stage: 'postgres_audit_insert_placeholder',
  mode: 'placeholder_no_credentials',
  table: 'infraops_audit.audit_events',
  event_type: 'triage.recommendation.created',
  action_class: 'read_only',
  sql_preview: 'INSERT INTO infraops_audit.audit_events (...) VALUES (...);',
  note: 'This demo node previews the audit insert. The runnable shell demo performs a real local Postgres insert.'
};
return [{ json: { ...item, postgres_audit_insert_placeholder: auditInsert } }];

const item = $input.first().json;
const documentation = {
  stage: 'documentation',
  mode: 'mock-ai-agent-placeholder',
  incident_note: `InvoiceBridge is experiencing elevated 5xx responses in ${item.alert.environment}. ${item.release_correlation.finding}`,
  operator_handoff: 'Continue read-only diagnosis and request human approval before rollback, restart, scaling, configuration change, or external communication.'
};
const slackSummary = {
  stage: 'slack_summary_placeholder',
  mode: 'placeholder_no_credentials',
  channel: '#mock-incident-triage',
  message_preview: [
    `Incident: ${item.alert.incident_id}`,
    `Service: ${item.alert.service}`,
    `Status: human_review_required`,
    `Runbook: ${item.runbook_lookup.selected_runbook}`,
    'No Slack API call was made.'
  ].join('\n')
};
const finalSummary = {
  incident_id: item.alert.incident_id,
  service: item.alert.service,
  environment: item.alert.environment,
  severity: item.alert.severity,
  status: 'human_review_required',
  likely_cause: 'Recent release changed renderer timeout or webhook retry behavior; mock confidence is medium.',
  recommended_next_step: 'Continue read-only checks and draft a human approval request for any rollback or config change.',
  approval_required: true,
  safety: {
    external_api_calls: 0,
    production_changes: 0,
    credentials_required_for_import: false
  }
};
return [{ json: { ...item, documentation, slack_summary_placeholder: slackSummary, final_summary: finalSummary } }];
